import sys


def solve():
    input_data = sys.stdin.read().strip()
    if not input_data:
        return
    n = int(input_data)

    steps = 0
    while n > 0:
        max_digit = 0
        temp = n
        while temp > 0:
            d = temp % 10
            if d > max_digit:
                max_digit = d
            temp //= 10
        n -= max_digit
        steps += 1

    print(steps)


if __name__ == "__main__":
    solve()
